import{_ as n,C as r,o as s,c as l,j as t,a,E as i,a2 as d}from"./chunks/framework.Di-jvWLj.js";const y=JSON.parse('{"title":"Kubernetes & Flux","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/kubernetes.md","filePath":"deployment/kubernetes.md","lastUpdated":1792501536000}'),c={name:"deployment/kubernetes.md"},h={id:"kubernetes-flux",tabindex:"-1"};function p(u,e,m,g,b,x){const o=r("Badge");return s(),l("div",null,[t("h1",h,[e[0]||(e[0]=a("Kubernetes & Flux ",-1)),i(o,{type:"warning",text:"Planned"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#kubernetes-flux","aria-label":'Permalink to "Kubernetes & Flux <Badge type="warning" text="Planned" />"'},"​",-1))]),e[3]||(e[3]=d('<div class="warning custom-block"><p class="custom-block-title">Planned</p><p>The Helm chart and the template&#39;s Flux manifests do not exist yet.</p></div><h2 id="helm-chart" tabindex="-1">Helm chart <a class="header-anchor" href="#helm-chart" aria-label="Permalink to &quot;Helm chart&quot;">​</a></h2><p>One shared chart, published to an OCI registry and used by every agent app. Planned contents:</p><ul><li><strong>Deployment</strong> with liveness (<code>/healthz</code>), readiness (<code>/readyz</code>) and startup probes, a long <code>terminationGracePeriodSeconds</code> (about 120 s) and a short <code>preStop</code> sleep, so the app fails readiness, drains and exits cleanly.</li><li><strong>Service</strong> and an optional <strong>Ingress</strong> for webhooks, the API and the UI.</li><li><strong><code>envFrom</code></strong> for one or more Secrets.</li><li>Optional <strong>CronJobs</strong> for the one-shot <code>run-job</code> mode.</li><li>When sandboxes are enabled: a <strong>ServiceAccount and Role</strong> to create, exec into and delete sandbox pods, and a <strong>NetworkPolicy</strong> that limits sandbox egress to DNS, the npm registry and GitHub.</li><li>An optional <strong>ServiceMonitor</strong> for Prometheus.</li></ul><p>The values stay small: image, environment, Secrets, ingress, replicas, sandbox and cron jobs.</p><h2 id="graceful-shutdown" tabindex="-1">Graceful shutdown <a class="header-anchor" href="#graceful-shutdown" aria-label="Permalink to &quot;Graceful shutdown&quot;">​</a></h2><p>On <code>SIGTERM</code> the app fails readiness first, stops the scheduler, stops intake, then calls <code>engine.drain()</code> within its budget. Runs still in progress are marked <code>interrupted</code> and recovered by another replica or the next pod. The drain deadline must be shorter than the grace period. This part already works in core: see <a href="/guide/recovery#drain">Cancel, Drain &amp; Recovery</a>.</p><h2 id="flux" tabindex="-1">Flux <a class="header-anchor" href="#flux" aria-label="Permalink to &quot;Flux&quot;">​</a></h2><p>Each agent repository gets:</p><ul><li>an <code>OCIRepository</code> for the chart and a <code>HelmRelease</code> with its values,</li><li>an <code>ImageRepository</code> and an <code>ImagePolicy</code> that select the newest <code>main-&lt;sha&gt;-&lt;timestamp&gt;</code> tag (or a semver range),</li><li>an image update marker in the <code>HelmRelease</code>, so Flux commits new tags back to the repository.</li></ul><h2 id="sandboxes-in-the-cluster" tabindex="-1">Sandboxes in the cluster <a class="header-anchor" href="#sandboxes-in-the-cluster" aria-label="Permalink to &quot;Sandboxes in the cluster&quot;">​</a></h2><p>Untrusted code runs in one pod per workspace: non-root, a read-only root filesystem except the workspace, CPU, memory and time limits, no service account token, no agent Secrets, and the egress-limiting NetworkPolicy. A short-lived, narrowly scoped GitHub token is injected only when a tool must push. Orphaned sandbox pods are garbage-collected.</p><h2 id="replicas" tabindex="-1">Replicas <a class="header-anchor" href="#replicas" aria-label="Permalink to &quot;Replicas&quot;">​</a></h2><p>See <a href="/deployment/replicas">Multiple Replicas</a>.</p>',14))])}const k=n(c,[["render",p]]);export{y as __pageData,k as default};
